
[data-theme="cyberpunk"] {
  --bg-primary: #0b0d11;
  --bg-secondary: #1b1d22;
  --bg-tertiary: #26282e;
  --bg-bubble-user: #f9bc31;
  --bg-bubble-agent: #1b1d22;
  --border-color: #3a3d44;
  --text-primary: #fff8df;
  --text-secondary: #d7c7a3;
  --text-muted: #8a8a7a;
  --accent: #f9bc31;
  --accent-glow: rgba(249, 188, 49, 0.25);
  --accent-hover: #f1a819;
  --header-gradient: linear-gradient(135deg, #0b0d11 0%, #1b1d22 50%, #0b0d11 100%);
  --button-gradient: linear-gradient(135deg, #f1a819 0%, #f9bc31 100%);
  --theme-name: "Cyberpunk Ops";
  --bg-image-desktop: url("data:image/png;base64,");
  --bg-image-mobile: url("data:image/png;base64,");
}

/* Official background watermark: real art at low opacity per spec */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image: var(--bg-image-desktop);
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  opacity: 0.20;
}
@media (max-width: 700px) {
  body::before {
    background-image: var(--bg-image-mobile);
    opacity: 0.15;
  }
}

/* Apply theme variables to existing structure */
body { background: var(--bg-primary) !important; }

#sidebar {
  background: var(--bg-primary) !important;
  border-color: var(--border-color) !important;
}

#sidebar .border-neutral-800 { border-color: var(--border-color) !important; }
#sidebar h1 {
  background: var(--header-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

main { background: transparent !important; }
main header {
  background: var(--header-gradient) !important;
  border-color: var(--border-color) !important;
}
main .border-neutral-800 { border-color: var(--border-color) !important; }

.bubble-user {
  background: var(--bg-bubble-user) !important;
  color: #000 !important;
  box-shadow: 0 0 20px var(--accent-glow);
}
.bubble-agent {
  background: var(--bg-bubble-agent) !important;
  border: 1px solid var(--border-color);
  color: var(--text-primary) !important;
}

#chat-list .sidebar-item.active { background: var(--bg-tertiary) !important; }
#chat-list .sidebar-item:hover { background: var(--bg-secondary) !important; }

#input {
  background: var(--bg-tertiary) !important;
  border-color: var(--border-color) !important;
  color: var(--text-primary) !important;
}
#input:focus { border-color: var(--accent) !important; }
#input::placeholder { color: var(--text-muted); }

#composer button[type="submit"] {
  background: var(--button-gradient) !important;
  box-shadow: 0 0 15px var(--accent-glow);
}
#composer button[type="submit"]:hover { filter: brightness(1.1); }

#mode-toggle {
  border-color: var(--border-color) !important;
  color: var(--text-secondary) !important;
}

#activity-btn, #arcade-btn, #theme-btn {
  border: 1px solid var(--border-color) !important;
  color: var(--text-secondary) !important;
}
#activity-btn:hover, #arcade-btn:hover, #theme-btn:hover {
  background: var(--bg-tertiary) !important;
  box-shadow: 0 0 10px var(--accent-glow);
}

#activity-panel { background: var(--bg-secondary) !important; border-color: var(--border-color) !important; }
#activity-panel .bg-neutral-900 { background: var(--bg-tertiary) !important; }

/* Theme picker dropdown */
#theme-picker {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  box-shadow: 0 8px 32px rgba(0,0,0,0.5);
}
#theme-picker button:hover { background: var(--bg-tertiary); }
#theme-picker .theme-active { border-color: var(--accent) !important; }

/* Scrollbar theming */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: var(--accent); }

/* Typing dots */
.typing-dot { color: var(--accent); }

/* Health dot stays semantic */
#health-dot.bg-green-500 { background-color: #22c55e !important; }
#health-dot.bg-yellow-500 { background-color: #eab308 !important; }
#health-dot.bg-red-500 { background-color: #ef4444 !important; }
#health-dot.bg-neutral-600 { background-color: var(--text-muted) !important; }

/* Reduced motion support per official spec */
@media (prefers-reduced-motion: reduce) {
  .typing-dot { animation: none !important; }
}
